// @module vendor-frontend | Vendora v1.0 | SPIT Mini Project AY 2026-27
import { Eye, Pencil, Trash2 } from 'lucide-react';
export default function ProductsTable({ products = [], onEdit, onDelete }) {
  return <div className="overflow-x-auto rounded-2xl border border-slate-200 bg-white"><table className="min-w-full text-left text-sm"><thead className="bg-slate-50 text-[10px] font-bold uppercase tracking-wider text-slate-500"><tr><th className="px-4 py-3">Product</th><th className="px-4 py-3">Category</th><th className="px-4 py-3">Price</th><th className="px-4 py-3">Stock</th><th className="px-4 py-3">Status</th><th className="px-4 py-3 text-right">Actions</th></tr></thead><tbody className="divide-y divide-slate-100">{products.map((product)=><tr key={product.product_id} className="hover:bg-violet-50/40"><td className="px-4 py-3"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-violet-50 text-xl">{product.category_emoji||'🛍️'}</span><div><p className="max-w-xs font-semibold text-slate-900">{product.name}</p><p className="text-xs text-slate-400">#{product.product_id}</p></div></div></td><td className="px-4 py-3"><span className="rounded-full bg-slate-100 px-2 py-1 text-xs font-semibold text-slate-600">{product.category_name}</span></td><td className="px-4 py-3 font-mono font-bold">₹{Number(product.price).toLocaleString('en-IN')}</td><td className={`px-4 py-3 font-bold ${product.stock_qty<=3?'text-red-600':'text-slate-700'}`}>{product.stock_qty}</td><td className="px-4 py-3"><span className={`rounded-full px-2 py-1 text-xs font-bold ${product.is_active?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-500'}`}>{product.is_active?'Active':'Archived'}</span></td><td className="px-4 py-3"><div className="flex justify-end gap-1"><button title="View" className="rounded-lg p-2 text-slate-400 hover:bg-slate-100 hover:text-slate-700"><Eye className="h-4 w-4"/></button><button title="Edit" onClick={()=>onEdit(product)} className="rounded-lg p-2 text-slate-400 hover:bg-violet-50 hover:text-violet-700"><Pencil className="h-4 w-4"/></button><button title="Archive" onClick={()=>onDelete(product)} className="rounded-lg p-2 text-slate-400 hover:bg-red-50 hover:text-red-600"><Trash2 className="h-4 w-4"/></button></div></td></tr>)}</tbody></table>{!products.length&&<div className="p-10 text-center text-sm text-slate-500">No products found.</div>}</div>;
}
